package com.oracle.banking.notification.exception;
import com.oracle.banking.shared.response.ErrorResponse; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.ConstraintViolationException; import org.springframework.http.*; import org.springframework.web.bind.*; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class,ConstraintViolationException.class}) ResponseEntity<ErrorResponse> bad(Exception e,HttpServletRequest r){return error(HttpStatus.BAD_REQUEST,e instanceof IllegalArgumentException?e.getMessage():"Invalid request",r);}@ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> general(Exception e,HttpServletRequest r){return error(HttpStatus.INTERNAL_SERVER_ERROR,"An unexpected error occurred",r);}private ResponseEntity<ErrorResponse> error(HttpStatus s,String m,HttpServletRequest r){return ResponseEntity.status(s).body(ErrorResponse.of(m,r.getRequestURI()));}}
